// ─── GHL API HELPERS ──────────────────────────────────────────────────────────
async function ghlVerifyAccess(email) {
  // Calls our serverless function — GHL token never exposed to browser
  try {
    const res = await fetch("/api/verify-access", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });
    if (!res.ok) return { granted: false, reason: "server_error" };
    return await res.json();
  } catch {
    return { granted: false, reason: "exception" };
  }
}

async function ghlSaveResults(contactId, taproot, taprootImageUrl, constellation, constellationImageUrls, version) {
  // Calls our serverless function — GHL token never exposed to browser
  try {
    const res = await fetch("/api/save-results", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ contactId, taproot, taprootImageUrl, constellation, constellationImageUrls, version }),
    });
    return res.ok;
  } catch (e) {
    console.error("GHL save error:", e);
    return false;
  }
}

// ─── SUPABASE HELPERS ─────────────────────────────────────────────────────────
async function sbGetRecord(email) {
  const { data } = await supabase
    .from("assessments_160")
    .select("*")
    .eq("email", email)
    .single();
  return data || null;
}

async function sbUpsertRecord(record) {
  await supabase.from("assessments_160").upsert(record, { onConflict: "email" });
}

async function sbSaveAnswer(email, questionIndex, answerId, score) {
  // Fetch current answers then merge
  const rec = await sbGetRecord(email);
  const answers = rec?.answers || {};
  answers[answerId] = score;
  await supabase
    .from("assessments_160")
    .update({ answers, last_question_index: questionIndex })
    .eq("email", email);
}

async function sbMarkComplete(email, taproot, constellation) {
  await supabase
    .from("assessments_160")
    .update({
      completed_at: new Date().toISOString(),
      root_taproot: taproot,
      root_constellation_1: constellation[0] || null,
      root_constellation_2: constellation[1] || null,
      root_constellation_3: constellation[2] || null,
      root_constellation_4: constellation[3] || null,
      root_constellation_5: constellation[4] || null,
      assessment_version: VERSION,
    })
    .eq("email", email);
}

// ─── SCORING ──────────────────────────────────────────────────────────────────
function scoreAnswers(statements, answers) {
  const scores = {};
  Object.keys(ROOTS).forEach((c) => (scores[c] = 0));
  statements.forEach((s) => {
    const val = answers[s.id];
    if (val !== undefined) {
      const adjusted = s.reverse ? 6 - val : val;
      scores[s.rootCode] = (scores[s.rootCode] || 0) + adjusted;
    }
  });
  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const taproot = sorted[0][0];
  const constellation = sorted.slice(1, 6).map(([code]) => code); // top 5 after primary
  return { taproot, constellation, scores };
}

// ─── SHUFFLE ──────────────────────────────────────────────────────────────────
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
