// ─── SCREEN: EMAIL GATE ───────────────────────────────────────────────────────
function EmailGate({ onVerified, onDenied, onAlreadyDone }) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("idle"); // idle | checking | error
  const [errorMsg, setErrorMsg] = useState("");

  const handleSubmit = async () => {
    if (!email.includes("@")) { setErrorMsg("Please enter a valid email address."); return; }
    setStatus("checking");
    setErrorMsg("");

    try {
      const cleanEmail = email.toLowerCase().trim();

      // 1. Verify access via serverless function (checks GHL tag securely)
      const access = await ghlVerifyAccess(cleanEmail);
      if (!access.granted) {
        setStatus("idle");
        onDenied(email);
        return;
      }

      // 2. Check Supabase for completion or prior progress
      const rec = await sbGetRecord(cleanEmail);

      if (rec?.completed_at) {
        setStatus("idle");
        onAlreadyDone();
        return;
      }

      // 3. Access granted — create Supabase record if first visit
      if (!rec) {
        await sbUpsertRecord({
          email: cleanEmail,
          access_verified: true,
          started_at: new Date().toISOString(),
          last_question_index: 0,
          answers: {},
        });
      }

      const resumeIndex = rec?.last_question_index || 0;
      const savedAnswers = rec?.answers || {};
      onVerified({
        email: cleanEmail,
        contactId: access.contactId,
        resumeIndex,
        savedAnswers,
      });
    } catch (e) {
      setStatus("idle");
      setErrorMsg("Something went wrong. Please try again.");
    }
  };

  return (
    <div style={{
      minHeight: "100vh", display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      background: `linear-gradient(170deg, ${G.darkBrown} 0%, ${G.black} 60%)`,
      padding: "2rem", textAlign: "center"
    }}>
      <p style={{ fontFamily: G.script, fontSize: "clamp(1.8rem,5vw,2.8rem)", color: G.gold, marginBottom: "0.5rem" }}>
        Her Million Dollar Return™
      </p>
      <div style={{ width: 60, height: 1, background: G.gold, opacity: 0.4, margin: "1rem auto" }} />
      <h2 style={{ fontFamily: G.display, fontSize: "clamp(1.4rem,3vw,2rem)", color: G.cream, fontWeight: 300, marginBottom: "0.75rem" }}>
        Enter Your Email to Begin
      </h2>
      <p style={{ fontFamily: G.serif, fontSize: "1rem", color: G.linen, opacity: 0.7, marginBottom: "2rem", maxWidth: 440 }}>
        We'll verify your access and resume exactly where you left off if you've started before.
      </p>

      <div style={{ width: "100%", maxWidth: 420 }}>
        <input
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          onKeyDown={e => e.key === "Enter" && handleSubmit()}
          placeholder="your@email.com"
          style={{
            width: "100%", padding: "1rem 1.2rem", background: `${G.darkBrown}88`,
            border: `1px solid ${G.gold}44`, color: G.cream, fontFamily: G.serif,
            fontSize: "1rem", outline: "none", marginBottom: "1rem",
            boxSizing: "border-box"
          }}
        />
        {errorMsg && (
          <p style={{ color: "#c0392b", fontFamily: G.serif, fontSize: "0.9rem", marginBottom: "1rem" }}>{errorMsg}</p>
        )}
        <button
          onClick={handleSubmit}
          disabled={status === "checking"}
          style={{
            width: "100%", padding: "1rem", background: status === "checking" ? G.darkBrown : G.gold,
            border: "none", color: G.black, fontFamily: G.serif, fontSize: "1rem",
            letterSpacing: "0.15em", textTransform: "uppercase", cursor: status === "checking" ? "default" : "pointer"
          }}
        >
          {status === "checking" ? "Verifying Access..." : "Continue"}
        </button>
      </div>
      <p style={{ fontFamily: G.serif, fontSize: "0.75rem", color: G.linen, opacity: 0.3, marginTop: "3rem", letterSpacing: "0.1em" }}>
        v{VERSION}
      </p>
    </div>
  );
}

