// ─── SCREEN: ASSESSMENT ───────────────────────────────────────────────────────
function Assessment({ statements, startIndex, savedAnswers, email, onComplete }) {
  const [qIdx, setQIdx] = useState(startIndex);
  const [answers, setAnswers] = useState(savedAnswers);
  const [visible, setVisible] = useState(true);
  const saveTimeout = useRef(null);

  const current = statements[qIdx];
  const selected = answers[current?.id];
  const progress = Math.round((qIdx / statements.length) * 100);

  const handleSelect = useCallback(async (score) => {
    const newAnswers = { ...answers, [current.id]: score };
    setAnswers(newAnswers);

    // Debounced Supabase save
    clearTimeout(saveTimeout.current);
    saveTimeout.current = setTimeout(async () => {
      await sbSaveAnswer(email, qIdx + 1, current.id, score);
    }, 800);

    if (qIdx < statements.length - 1) {
      setVisible(false);
      setTimeout(() => { setQIdx(q => q + 1); setVisible(true); }, 200);
    } else {
      onComplete(newAnswers);
    }
  }, [answers, current, qIdx, email, statements.length, onComplete]);

  const handleBack = () => {
    if (qIdx > 0) {
      setVisible(false);
      setTimeout(() => { setQIdx(q => q - 1); setVisible(true); }, 200);
    }
  };

  useEffect(() => { window.scrollTo({ top: 0, behavior: "smooth" }); }, [qIdx]);

  const scale = [
    { v: 1, l: "Almost Never" },
    { v: 2, l: "Rarely" },
    { v: 3, l: "Sometimes" },
    { v: 4, l: "Often" },
    { v: 5, l: "Almost Always" },
  ];

  return (
    <div style={{
      minHeight: "100vh", display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "space-between",
      background: `linear-gradient(170deg, ${G.darkBrown} 0%, ${G.black} 45%, ${G.wine}33 100%)`,
      padding: "2rem 1rem"
    }}>
      {/* Header */}
      <div style={{ width: "100%", maxWidth: 680, marginBottom: "1.5rem" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.6rem" }}>
          <p style={{ fontFamily: G.serif, fontSize: "0.8rem", color: G.linen, opacity: 0.5, letterSpacing: "0.15em", textTransform: "uppercase" }}>
            Root Discovery Assessment™
          </p>
          <p style={{ fontFamily: G.serif, fontSize: "0.8rem", color: G.linen, opacity: 0.5 }}>
            {qIdx + 1} / {statements.length}
          </p>
        </div>
        <div style={{ width: "100%", height: 2, background: `${G.gold}22`, borderRadius: 1 }}>
          <div style={{ width: `${progress}%`, height: "100%", background: G.gold, borderRadius: 1, transition: "width 0.4s ease" }} />
        </div>
      </div>

      {/* Statement */}
      <div style={{
        flex: 1, display: "flex", flexDirection: "column", alignItems: "center",
        justifyContent: "center", width: "100%", maxWidth: 620,
        opacity: visible ? 1 : 0, transition: "opacity 0.2s ease"
      }}>
        <p style={{
          fontFamily: G.serif, fontSize: "clamp(1.05rem,2.5vw,1.35rem)",
          color: G.linen, lineHeight: 1.75, textAlign: "center",
          marginBottom: "3rem", padding: "0 0.5rem"
        }}>
          {current?.text}
        </p>

        {/* Likert Scale */}
        <div style={{ display: "flex", justifyContent: "center", gap: "clamp(0.4rem,1.5vw,1rem)", flexWrap: "wrap" }}>
          {scale.map(({ v, l }) => {
            const isSelected = selected === v;
            return (
              <button
                key={v}
                onClick={() => handleSelect(v)}
                style={{
                  display: "flex", flexDirection: "column", alignItems: "center", gap: "0.5rem",
                  padding: "1rem clamp(0.6rem,2vw,1.2rem)",
                  minWidth: "clamp(55px,12vw,80px)",
                  background: isSelected ? G.gold : `${G.darkBrown}66`,
                  border: `1px solid ${isSelected ? G.gold : G.gold + "44"}`,
                  color: isSelected ? G.black : G.linen,
                  fontFamily: G.serif, cursor: "pointer",
                  transition: "all 0.2s"
                }}
              >
                <span style={{ fontSize: "1.3rem", fontWeight: 600 }}>{v}</span>
                <span style={{ fontSize: "clamp(0.6rem,1.5vw,0.72rem)", letterSpacing: "0.05em", textAlign: "center", lineHeight: 1.2 }}>{l}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Footer / Back */}
      <div style={{ width: "100%", maxWidth: 680, marginTop: "2rem", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        {qIdx > 0 ? (
          <button onClick={handleBack} style={{
            background: "none", border: "none", color: G.linen, opacity: 0.45,
            fontFamily: G.serif, fontSize: "0.85rem", letterSpacing: "0.1em",
            cursor: "pointer", padding: 0
          }}>
            ← Back
          </button>
        ) : <span />}
        <p style={{ fontFamily: G.serif, fontSize: "0.7rem", color: G.linen, opacity: 0.25, letterSpacing: "0.1em" }}>
          v{VERSION}
        </p>
      </div>
    </div>
  );
}

// ─── SCREEN: LOADING ──────────────────────────────────────────────────────────
function Loading({ onDone }) {
  const messages = [
    "Mapping your Root System...",
    "Tracing the pattern beneath the pattern...",
    "Identifying your Root Constellation...",
    "Preparing your full discovery...",
  ];
  const [msgIdx, setMsgIdx] = useState(0);

  useEffect(() => {
    let count = 0;
    const iv = setInterval(() => {
      count++;
      if (count >= messages.length) {
        clearInterval(iv);
        setTimeout(onDone, 800);
      } else {
        setMsgIdx(count);
      }
    }, 1200);
    return () => clearInterval(iv);
  }, []);

  return (
    <div style={{
      minHeight: "100vh", display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      background: `radial-gradient(ellipse at 50% 40%, ${G.wine}99, ${G.black} 70%)`,
      padding: "2rem", textAlign: "center"
    }}>
      <p style={{ fontFamily: G.script, fontSize: "clamp(2rem,6vw,3rem)", color: G.gold, marginBottom: "2rem" }}>
        Her Million Dollar Return™
      </p>
      <div style={{ width: 40, height: 1, background: G.gold, opacity: 0.4, margin: "0 auto 2rem" }} />
      <p style={{ fontFamily: G.display, fontSize: "clamp(1.1rem,3vw,1.5rem)", color: G.linen, fontStyle: "italic", minHeight: "2.5rem", transition: "opacity 0.4s" }}>
        {messages[msgIdx]}
      </p>
    </div>
  );
}

