// ─── APP ──────────────────────────────────────────────────────────────────────
export default function App() {
  const [screen, setScreen] = useState("welcome");
  const [userInfo, setUserInfo] = useState(null);
  const [shuffledStatements, setShuffledStatements] = useState([]);
  const [results, setResults] = useState(null);
  const [deniedEmail, setDeniedEmail] = useState("");

  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = gFonts;
    document.head.appendChild(link);
    const style = document.createElement("style");
    style.textContent = `*{margin:0;padding:0;box-sizing:border-box}html,body{background:#020202;color:#f9f6f4;font-family:'EB Garamond',Georgia,serif}button{font-family:inherit}input{font-family:inherit}`;
    document.head.appendChild(style);
    setShuffledStatements(shuffle(STATEMENTS));
  }, []);

  useEffect(() => { window.scrollTo({ top: 0, behavior: "smooth" }); }, [screen]);

  const handleVerified = (info) => {
    setUserInfo(info);
    setScreen("assessment");
  };

  const handleComplete = async (answers) => {
    setScreen("loading");
    const { taproot, constellation } = scoreAnswers(shuffledStatements, answers);

    // Save to Supabase
    await sbMarkComplete(userInfo.email, taproot, constellation);

    // Write results to GHL via serverless function (token protected)
    const rootNames = constellation.map(c => ROOTS[c]?.name || c);
    const rootImageUrls = constellation.map(c => rootImageUrl(c));
    await ghlSaveResults(
      userInfo.contactId,
      ROOTS[taproot]?.name || taproot,
      rootImageUrl(taproot),
      rootNames,
      rootImageUrls,
      VERSION
    );

    setResults({ taproot, constellation });
    setTimeout(() => setScreen("results"), 200);
  };

  if (screen === "welcome") return <Welcome onBegin={() => setScreen("email")} />;
  if (screen === "email") return (
    <EmailGate
      onVerified={handleVerified}
      onDenied={(email) => { setDeniedEmail(email); setScreen("denied"); }}
      onAlreadyDone={() => setScreen("completed")}
    />
  );
  if (screen === "denied") return <AccessDenied email={deniedEmail} />;
  if (screen === "completed") return <AlreadyCompleted />;
  if (screen === "assessment" && userInfo && shuffledStatements.length > 0) return (
    <Assessment
      statements={shuffledStatements}
      startIndex={userInfo.resumeIndex}
      savedAnswers={userInfo.savedAnswers}
      email={userInfo.email}
      onComplete={handleComplete}
    />
  );
  if (screen === "loading") return <Loading onDone={() => results && setScreen("results")} />;
  if (screen === "results" && results) return (
    <Results
      taproot={results.taproot}
      constellation={results.constellation}
      onRestart={() => setScreen("welcome")}
    />
  );
  return null;
}
